-- 0065: 聊天审批卡片(Lark / Telegram)。与 migrations/0065_chat_cards.sql 同一份结构,说明见那边;
-- 类型映射与命名规则见 internal/bootstrap/pgschema_test.go,TestPGSchemaMatchesMySQL 逐列比对。
--
-- 全部写成可重跑的(IF NOT EXISTS),理由同 ADR 0016。
CREATE TABLE IF NOT EXISTS "tbl_chat_binding" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "channel" citext NOT NULL CHECK (char_length("channel") <= 16),
  "bot_id" citext NOT NULL CHECK (char_length("bot_id") <= 64),
  "account_id" citext NOT NULL CHECK (char_length("account_id") <= 64),
  "chat_id" citext NOT NULL DEFAULT '' CHECK (char_length("chat_id") <= 64),
  "created_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_chat_binding__uk_chat_binding_user" ON "tbl_chat_binding" ("channel", "user_id");
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_chat_binding__uk_chat_binding_account" ON "tbl_chat_binding" ("channel", "bot_id", "account_id");

CREATE TABLE IF NOT EXISTS "tbl_chat_bind_code" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "channel" citext NOT NULL CHECK (char_length("channel") <= 16),
  "code_hash" citext NOT NULL CHECK (char_length("code_hash") <= 64),
  "expires_at" timestamptz(3) NOT NULL,
  "used_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_chat_bind_code__uk_chat_bind_code" ON "tbl_chat_bind_code" ("code_hash");
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_chat_bind_code__uk_chat_bind_code_user" ON "tbl_chat_bind_code" ("channel", "user_id");

CREATE TABLE IF NOT EXISTS "tbl_chat_card" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "approval_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "channel" citext NOT NULL CHECK (char_length("channel") <= 16),
  "bot_id" citext NOT NULL DEFAULT '' CHECK (char_length("bot_id") <= 64),
  "state" citext NOT NULL DEFAULT 'queued' CHECK (char_length("state") <= 16),
  "chat_id" citext NOT NULL DEFAULT '' CHECK (char_length("chat_id") <= 64),
  "message_id" citext NOT NULL DEFAULT '' CHECK (char_length("message_id") <= 128),
  "token_hash" citext NOT NULL DEFAULT '' CHECK (char_length("token_hash") <= 64),
  "partial" boolean NOT NULL DEFAULT false,
  "source_truncated" boolean NOT NULL DEFAULT false,
  "attempts" integer NOT NULL DEFAULT 0,
  "next_at" timestamptz(3) NOT NULL,
  "last_error" citext NOT NULL DEFAULT '' CHECK (char_length("last_error") <= 255),
  "created_at" timestamptz(3),
  "updated_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_chat_card__uk_chat_card" ON "tbl_chat_card" ("approval_id", "user_id", "channel");
CREATE INDEX IF NOT EXISTS "tbl_chat_card__idx_chat_card_token" ON "tbl_chat_card" ("token_hash");
CREATE INDEX IF NOT EXISTS "tbl_chat_card__idx_chat_card_state" ON "tbl_chat_card" ("state", "next_at");

ALTER TABLE "tbl_approval"
  ADD COLUMN IF NOT EXISTS "decided_via" citext NOT NULL DEFAULT '' CHECK (char_length("decided_via") <= 16),
  ADD COLUMN IF NOT EXISTS "reject_reason" citext NOT NULL DEFAULT '' CHECK (char_length("reject_reason") <= 512);
